sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var ga = new GlideAjax('x_2002450_nec_tr_0.getweatherinfo');
    ga.addParam('sysparm_name', 'getCallerDetails');
    ga.addParam('sysparm_caller_id', newValue);
    ga.getXMLAnswer(function(response) {
        var result = JSON.parse(response);

        g_form.setValue('manager',result.manager);
        g_form.setValue('title', result.title);
    });
}
